func getEffectiveBackend(cmd *cobra.Command) (string, error) {
	// Check flag changed
	backend := backendFlag
	if !cmd.Flags().Changed("backend") && !cmd.Root().PersistentFlags().Changed("backend") {
		// Actually need to check root persistent flag changed
		// We already have global var backendFlag set to default ssm or env? Let's handle env.
		if env := os.Getenv("CHAMBER_SECRET_BACKEND"); env != "" {
			backend = env
		}
	}
	// If still empty, default is ssm (already set)
	if backend == "" {
		backend = "ssm"
	}
	return backend, nil
}

func getEffectiveS3Bucket(cmd *cobra.Command) string {
	bucket := backendS3BucketFlag
	if !cmd.Root().PersistentFlags().Changed("backend-s3-bucket") && !cmd.Flags().Changed("backend-s3-bucket") {
		if env := os.Getenv("CHAMBER_S3_BUCKET"); env != "" {
			bucket = env
		}
	}
	return bucket
}

func getEffectiveKmsAlias(cmd *cobra.Command) string {
	alias := kmsKeyAliasFlag
	if !cmd.Root().PersistentFlags().Changed("kms-key-alias") && !cmd.Flags().Changed("kms-key-alias") {
		if env := os.Getenv("CHAMBER_KMS_KEY_ALIAS"); env != "" {
			alias = env
		}
	}
	if alias == "" {
		alias = "alias/parameter_store_key"
	}
	return alias
}

