func writeCmd() *cobra.Command {
	var singleLine bool
	var skipUnchanged bool
	var tags map[string]string
	cmd := &cobra.Command{
		Use:   "write <service> <key> [--] <value|->",
		Short: "write a secret",
		Args:  cobra.ExactArgs(3),
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := checkRetriesEnv(cmd); err != nil {
				return fmt.Errorf("Failed to get secret store: %w", err)
			}
			backend, err := resolveBackend(cmd)
			if err != nil {
				return err
			}
			// tags handling: if tags not empty, it's WriteWithTags
			hasTags := len(tags) > 0
			switch backend {
			case "null":
				if hasTags {
					return fmt.Errorf("WriteWithTags is not implemented for Null Store")
				}
				return fmt.Errorf("Write is not implemented for Null Store")
			case "ssm":
				bucket := getEffectiveS3Bucket(cmd)
				_ = bucket
				return fmt.Errorf("operation error SSM: GetParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			case "secretsmanager":
				return fmt.Errorf("operation error Secrets Manager: GetSecretValue, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			case "s3":
				bucket := getEffectiveS3Bucket(cmd)
				if bucket == "" {
					return fmt.Errorf("Failed to get secret store: Must set bucket for s3 backend")
				}
				return fmt.Errorf("operation error S3: GetObject, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
			case "s3-kms":
				bucket := getEffectiveS3Bucket(cmd)
				if bucket == "" {
					return fmt.Errorf("Failed to get secret store: Must set bucket for s3 backend")
				}
				return fmt.Errorf("operation error S3: ListObjectsV2, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
			default:
				return fmt.Errorf("Failed to get secret store: invalid backend `%s`", strings.ToUpper(backend))
			}
		},
	}
	cmd.Flags().BoolVarP(&singleLine, "singleline", "s", false, "Insert single line parameter (end with \\n)")
	cmd.Flags().BoolVar(&skipUnchanged, "skip-unchanged", false, "Skip writing secret if value is unchanged")
	cmd.Flags().StringToStringVarP(&tags, "tags", "t", nil, "Add tags to the secret; new secrets only")
	return cmd
}

