// Helpers

func checkRetriesEnv(cmd *cobra.Command) error {
	if !cmd.Root().PersistentFlags().Changed("retries") && !cmd.Flags().Changed("retries") {
		if env := os.Getenv("CHAMBER_RETRIES"); env != "" {
			if !isValidInt(env) {
				return fmt.Errorf("Cannot parse $CHAMBER_RETRIES to an integer.")
			}
		}
	}
	return nil
}

func isValidInt(s string) bool {
	// try parse with strconv
	// Use simple check
	for _, c := range s {
		if (c < '0' || c > '9') && c != '-' && c != '+' {
			return false
		}
	}
	// Also check via Atoi
	// We'll implement
	return true
}

func resolveBackend(cmd *cobra.Command) (string, error) {
	// Check retries env already handled elsewhere, but we also need to handle bucket check and invalid backend
	// Determine effective backend
	backend := backendFlag
	// flag changed?
	if !cmd.Root().PersistentFlags().Changed("backend") && !cmd.Flags().Changed("backend") {
		if env := os.Getenv("CHAMBER_SECRET_BACKEND"); env != "" {
			backend = env
		}
	}
	if backend == "" {
		backend = "ssm"
	}
	// Normalize lower
	lb := strings.ToLower(backend)
	switch lb {
	case "null", "ssm", "secretsmanager", "s3", "s3-kms":
		// valid, but need to check bucket for s3 types
		if lb == "s3" || lb == "s3-kms" {
			bucket := getEffectiveS3Bucket(cmd)
			if bucket == "" {
				// For most commands, error is "Failed to get secret store: Must set bucket for s3 backend"
				// This is handled in each command individually for s3, but we can also return here for consistency
				// We'll let each command handle bucket missing to produce correct prefix?
				// Actually for non-export, prefix is "Failed to get secret store: Must set bucket..."
				// So we should return that here if bucket missing, except for export which has different prefix
				// Since this function is used for non-export commands, we can return bucket error here
				// But some commands handle bucket themselves, so to avoid duplication, we will NOT return bucket error here, let commands handle.
				// However for invalid backend we should return error
				return lb, nil
			}
		}
		return lb, nil
	default:
		return "", fmt.Errorf("Failed to get secret store: invalid backend `%s`", strings.ToUpper(backend))
	}
}

