	var m map[string]interface{}
	// Try using go.yaml.in/yaml/v3 via our hack? We have gopkg.in/yaml.v3
	// We'll try with gopkg.in/yaml.v3
	if err := yamlUnmarshal(data, &m); err != nil {
		return nil, err
	}
	if m == nil {
		// Could be empty? For "{}" it should be empty map? Actually yaml.v3 for "{}" gives empty map? Let's see
		// For empty json object, m would be empty map (0 keys) leading to success 0
		m = make(map[string]interface{})
		// Try again to check if it's actually empty
		// If data is "{}" or "{}\n", we should treat as 0
		trimmed := strings.TrimSpace(string(data))
		if trimmed == "{}" || trimmed == "{}\n" || trimmed == "" {
