			// retries env handling different for export
			if env := os.Getenv("CHAMBER_RETRIES"); env != "" {
				if !cmd.Root().PersistentFlags().Changed("retries") && !cmd.Flags().Changed("retries") {
					// try parse
					if !isValidInt(env) {
						return fmt.Errorf("Cannot parse $CHAMBER_RETRIES to an integer.")
					}
				}
			}
			backend, err := resolveBackendExport(cmd)
			if err != nil {
				return err
			}
			// format handling case-insensitive
			f := strings.ToLower(format)
			validFormats := map[string]bool{
				"json": true, "yaml": true, "java-properties": true, "csv": true, "tsv": true, "dotenv": true, "tfvars": true,
			}
			if !validFormats[f] {
				return fmt.Errorf("Unable to export parameters: Unsupported export format: %s", format)
			}
			// output file handling
			if outputFile != "" {
				// try open
				file, err := os.Create(outputFile)
				if err != nil {
					return fmt.Errorf("Failed to open output file for writing: %v", err)
				}
				file.Close()
				// For null backend, write {} or empty
				var content string
				switch f {
				case "json":
					content = "{}\n"
				case "yaml":
					content = "{}\n"
				case "java-properties", "csv", "tsv", "dotenv", "tfvars":
					content = ""
				default:
					content = "{}\n"
				}
				// Write to file
				if err := os.WriteFile(outputFile, []byte(content), 0644); err != nil {
					return fmt.Errorf("Failed to open output file for writing: %v", err)
				}
				return nil
			}
			// No output file, print to stdout
			switch backend {
			case "null":
				switch f {
				case "json":
					fmt.Println("{}")
				case "yaml":
					fmt.Println("{}")
				case "java-properties", "csv", "tsv", "dotenv", "tfvars":
					// print nothing
				}
				return nil
			case "ssm":
				// first service in args for error message
				svc := args[0]
				return fmt.Errorf("Failed to list store contents for service %s: operation error SSM: GetParametersByPath, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded", svc)
			case "secretsmanager":
				svc := args[0]
				return fmt.Errorf("Failed to list store contents for service %s: operation error Secrets Manager: GetSecretValue, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded", svc)
