				bucket := getEffectiveS3Bucket(cmd)
				if bucket == "" {
					return fmt.Errorf("Must set bucket for s3 backend")
				}
				svc := args[0]
				return fmt.Errorf("Failed to list store contents for service %s: operation error S3: GetObject, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.", svc)
			case "s3-kms":
				bucket := getEffectiveS3Bucket(cmd)
				if bucket == "" {
					return fmt.Errorf("Must set bucket for s3 backend")
				}
