func getEffectiveS3Bucket(cmd *cobra.Command) string {
	bucket := backendS3BucketFlag
	// check if flag changed
	if cmd.Root().PersistentFlags().Changed("backend-s3-bucket") || cmd.Flags().Changed("backend-s3-bucket") {
		return bucket
	}
	if cmd.PersistentFlags().Changed("backend-s3-bucket") {
		return bucket
	}
	if env := os.Getenv("CHAMBER_S3_BUCKET"); env != "" {
		return env
	}
	return bucket
}

func checkRetriesEnv(cmd *cobra.Command) error {
	if cmd.Root().PersistentFlags().Changed("retries") || cmd.Flags().Changed("retries") || cmd.PersistentFlags().Changed("retries") {
		return nil
	}
	if env := os.Getenv("CHAMBER_RETRIES"); env != "" {
		if _, err := strconv.Atoi(env); err != nil {
			return fmt.Errorf("Cannot parse $CHAMBER_RETRIES to an integer.")
		}
	}
	return nil
}

func resolveBackend(cmd *cobra.Command) (string, error) {
	backend := backendFlag
	if !cmd.Root().PersistentFlags().Changed("backend") && !cmd.Flags().Changed("backend") && !cmd.PersistentFlags().Changed("backend") {
		if env := os.Getenv("CHAMBER_SECRET_BACKEND"); env != "" {
			backend = env
		}
	}
	if backend == "" {
		backend = "ssm"
	}
	lb := strings.ToLower(backend)
	switch lb {
	case "null", "ssm", "secretsmanager", "s3", "s3-kms":
		return lb, nil
	default:
		return "", fmt.Errorf("Failed to get secret store: invalid backend `%s`", strings.ToUpper(backend))
	}
}

func resolveBackendExport(cmd *cobra.Command) (string, error) {
	backend := backendFlag
	if !cmd.Root().PersistentFlags().Changed("backend") && !cmd.Flags().Changed("backend") && !cmd.PersistentFlags().Changed("backend") {
		if env := os.Getenv("CHAMBER_SECRET_BACKEND"); env != "" {
			backend = env
		}
	}
	if backend == "" {
		backend = "ssm"
	}
	lb := strings.ToLower(backend)
	switch lb {
	case "null", "ssm", "secretsmanager", "s3", "s3-kms":
		bucket := getEffectiveS3Bucket(cmd)
		if (lb == "s3" || lb == "s3-kms") && bucket == "" {
