func execCmd() *cobra.Command {
	var pristine bool
	var strict bool
	var strictValue string
	cmd := &cobra.Command{
		Use:   "exec <service...> -- <command> [<arg...>]",
		Short: "Executes a command with secrets loaded into the environment",
		Long: `Executes a command with secrets loaded into the environment

Examples:

Given a secret store like this:

	$ echo '{"db_username": "root", "db_password": "hunter22"}' | chamber import - 

--strict will fail with unfilled env vars

	$ HOME=/tmp DB_USERNAME=chamberme DB_PASSWORD=chamberme EXTRA=chamberme chamber exec --strict service exec -- env
	chamber: extra unfilled env var EXTRA
	exit 1

--pristine takes effect after checking for --strict values

	$ HOME=/tmp DB_USERNAME=chamberme DB_PASSWORD=chamberme chamber exec --strict --pristine service exec -- env
	DB_USERNAME=root
	DB_PASSWORD=hunter22
`,
		RunE: func(cmd *cobra.Command, args []string) error {
			dash := cmd.ArgsLenAtDash()
			if dash == -1 {
				if len(args) == 0 {
					return fmt.Errorf("at least one service must be specified: requires at least 1 arg(s), only received 0")
				}
				return fmt.Errorf("please separate services and command with '--'. See usage")
			}
			if len(args) == 0 || dash == 0 {
				return fmt.Errorf("at least one service must be specified: requires at least 1 arg(s), only received 0")
			}
			if dash >= len(args) {
				return fmt.Errorf("must specify command to run. See usage: requires at least 1 arg(s), only received 0")
			}
			// services := args[:dash]
			commandArgs := args[dash:]

			if err := checkRetriesEnv(cmd); err != nil {
				return fmt.Errorf("Failed to get secret store: %w", err)
			}
			backend, err := resolveBackend(cmd)
			if err != nil {
				return err
			}
			switch backend {
			case "null":
				if strict {
					// Build map of env
					envMap := map[string]string{}
					for _, kv := range os.Environ() {
						parts := strings.SplitN(kv, "=", 2)
						k := parts[0]
						v := ""
						if len(parts) > 1 {
							v = parts[1]
						}
						envMap[k] = v
					}
					for k, v := range envMap {
						if v == strictValue {
							// fail for first occurrence (random map order)
							return fmt.Errorf("parent env was expecting %s=%s, but was not in store", k, v)
						}
					}
				}
				var env []string
				if pristine {
					env = []string{}
				} else {
					env = os.Environ()
				}
				return runCmd(commandArgs, env)
			case "ssm":
				return fmt.Errorf("Failed to list store contents: operation error SSM: GetParametersByPath, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			case "secretsmanager":
				return fmt.Errorf("Failed to list store contents: operation error Secrets Manager: GetSecretValue, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			case "s3":
				bucket := getEffectiveS3Bucket(cmd)
				if bucket == "" {
					return bucketMissingError()
				}
				return fmt.Errorf("Failed to list store contents: operation error S3: GetObject, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
			case "s3-kms":
				bucket := getEffectiveS3Bucket(cmd)
				if bucket == "" {
					return bucketMissingError()
				}
				return fmt.Errorf("Failed to list store contents: operation error S3: ListObjectsV2, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
			}
			return nil
		},
	}
	cmd.Flags().BoolVar(&pristine, "pristine", false, "only use variables retrieved from the backend; do not inherit existing environment variables")
	cmd.Flags().BoolVar(&strict, "strict", false, "enable strict mode:\nonly inject secrets for which there is a corresponding env var with value\n<strict-value>, and fail if there are any env vars with that value missing\nfrom secrets")
	cmd.Flags().StringVar(&strictValue, "strict-value", "chamberme", "value to expect in --strict mode")
	return cmd
}

func runCmd(args []string, env []string) error {
	c := exec.Command(args[0], args[1:]...)
	c.Env = env
	c.Stdin = os.Stdin
	c.Stdout = os.Stdout
	c.Stderr = os.Stderr
	err := c.Run()
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			if status, ok := exitErr.Sys().(syscall.WaitStatus); ok {
				os.Exit(status.ExitStatus())
			}
		}
		// File not found handling
		if strings.Contains(args[0], "/") {
			return fmt.Errorf("exec: \"%s\": stat %s: no such file or directory", args[0], args[0])
		}
		return fmt.Errorf("exec: \"%s\": executable file not found in $PATH", args[0])
	}
	return nil
}

