			if env := os.Getenv("CHAMBER_RETRIES"); env != "" {
				if !cmd.Root().PersistentFlags().Changed("retries") && !cmd.Flags().Changed("retries") && !cmd.PersistentFlags().Changed("retries") {
					if _, err := strconv.Atoi(env); err != nil {
						return fmt.Errorf("Cannot parse $CHAMBER_RETRIES to an integer.")
					}
				}
			}
			backend, err := resolveBackendExport(cmd)
			if err != nil {
				return err
			}
			f := strings.ToLower(format)
			valid := map[string]bool{"json": true, "yaml": true, "java-properties": true, "csv": true, "tsv": true, "dotenv": true, "tfvars": true}
			if !valid[f] {
				return fmt.Errorf("Unable to export parameters: Unsupported export format: %s", format)
