func checkRetriesEnv(cmd *cobra.Command) error {
	if cmd.Root().PersistentFlags().Changed("retries") || cmd.Flags().Changed("retries") || cmd.PersistentFlags().Changed("retries") {
		return nil
	}
	if env := os.Getenv("CHAMBER_RETRIES"); env != "" {
		if _, err := strconv.Atoi(env); err != nil {
			return fmt.Errorf("Cannot parse $CHAMBER_RETRIES to an integer.")
		}
	}
	return nil
