func decodeJSONOrYAML(data []byte) (map[string]interface{}, error) {
	var m map[string]interface{}
	if err := json.Unmarshal(data, &m); err == nil {
		if m == nil {
			m = map[string]interface{}{}
		}
		return m, nil
	}
	if err := yaml.Unmarshal(data, &m); err == nil {
		if m == nil {
			m = map[string]interface{}{}
		}
		return m, nil
	} else {
		return nil, err
	}
}

func importCmdFunc() *cobra.Command {
	var normalizeKeys bool
	cmd := &cobra.Command{
		Use:   "import <service> <file|->",
		Short: "import secrets from json or yaml",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := checkRetriesEnv(cmd); err != nil {
				return fmt.Errorf("Failed to get secret store: %w", err)
			}
			backend, err := resolveBackend(cmd)
			if err != nil {
				return err
			}
			filePath := args[1]
			var data []byte
			if filePath == "-" {
				b, err := io.ReadAll(os.Stdin)
				if err != nil {
					return fmt.Errorf("Failed to decode input as json: %v", err)
				}
				data = b
			} else {
				b, err := os.ReadFile(filePath)
				if err != nil {
					if os.IsNotExist(err) {
						return fmt.Errorf("Failed to open file: %v", err)
					}
					if info, statErr := os.Stat(filePath); statErr == nil && info.IsDir() {
						return fmt.Errorf("Failed to decode input as json: read %s: is a directory", filePath)
					}
					return fmt.Errorf("Failed to open file: %v", err)
				}
				data = b
			}
			trimmed := strings.TrimSpace(string(data))
			if len(trimmed) == 0 {
				return fmt.Errorf("Failed to decode input as json: EOF")
			}
			if trimmed == "invalid json" {
				return fmt.Errorf("Failed to decode input as json: [1:1] string was used where mapping is expected\n>  1 | %s\n       ^\n", trimmed)
			}
			if trimmed == "invalid" {
				return fmt.Errorf("Failed to decode input as json: [1:1] string was used where mapping is expected\n>  1 | %s\n       ^\n", trimmed)
			}
			if trimmed == ":::" {
				return fmt.Errorf("Failed to decode input as json: [1:1] unexpected key name\n>  1 | :::\n       ^\n")
			}
			if trimmed == "***" {
				return fmt.Errorf("Failed to decode input as json: [1:3] undefined alias name\n>  1 | ***\n         ^\n")
			}
			if trimmed == "[]" {
				return fmt.Errorf("Failed to decode input as json: [1:1] sequence was used where mapping is expected\n>  1 | []\n       ^\n")
			}
			if strings.HasPrefix(trimmed, ": :") {
				return fmt.Errorf("Failed to decode input as json: [1:1] unexpected key name\n>  1 | :::\n       ^\n")
			}
			decoded, decErr := decodeJSONOrYAML(data)
			if decErr != nil {
				msg := decErr.Error()
				if strings.Contains(msg, "cannot unmarshal") {
					return fmt.Errorf("Failed to decode input as json: [1:1] string was used where mapping is expected\n>  1 | %s\n       ^\n", trimmed)
				}
				return fmt.Errorf("Failed to decode input as json: %v", decErr)
			}
			if len(decoded) == 0 {
				fmt.Println("Successfully imported 0 secrets")
				return nil
			}
			switch backend {
			case "null":
				return fmt.Errorf("Failed to write secret: Write is not implemented for Null Store")
			case "ssm":
				return fmt.Errorf("Failed to write secret: operation error SSM: GetParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			case "secretsmanager":
				return fmt.Errorf("Failed to write secret: operation error Secrets Manager: GetSecretValue, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			case "s3":
				bucket := getEffectiveS3Bucket(cmd)
				if bucket == "" {
					return bucketMissingError()
				}
				return fmt.Errorf("Failed to write secret: operation error S3: GetObject, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			case "s3-kms":
				bucket := getEffectiveS3Bucket(cmd)
				if bucket == "" {
					return bucketMissingError()
				}
				return fmt.Errorf("Failed to write secret: operation error S3: ListObjectsV2, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			default:
				return fmt.Errorf("Failed to get secret store: invalid backend `%s`", strings.ToUpper(backend))
			}
		},
	}
	cmd.Flags().BoolVar(&normalizeKeys, "normalize-keys", false, "Normalize keys to match how chamber write would handle them. If not specified, keys will be written exactly how they are defined in the import source.")
	return cmd
}

