func getEffectiveS3Bucket(cmd *cobra.Command) string {
	bucket := backendS3BucketFlag
	if cmd.Root().PersistentFlags().Changed("backend-s3-bucket") || cmd.Flags().Changed("backend-s3-bucket") || cmd.PersistentFlags().Changed("backend-s3-bucket") {
		return bucket
	}
	if env := os.Getenv("CHAMBER_S3_BUCKET"); env != "" {
		return env
	}
	return bucket
}

func checkRetriesEnv(cmd *cobra.Command) error {
	if cmd.Root().PersistentFlags().Changed("retries") || cmd.Flags().Changed("retries") || cmd.PersistentFlags().Changed("retries") {
		return nil
	}
	if env := os.Getenv("CHAMBER_RETRIES"); env != "" {
		if _, err := strconv.Atoi(env); err != nil {
			return fmt.Errorf("Cannot parse $CHAMBER_RETRIES to an integer.")
		}
	}
	return nil
}

func resolveBackend(cmd *cobra.Command) (string, error) {
	backend := backendFlag
	if !cmd.Root().PersistentFlags().Changed("backend") && !cmd.Flags().Changed("backend") && !cmd.PersistentFlags().Changed("backend") {
		if env := os.Getenv("CHAMBER_SECRET_BACKEND"); env != "" {
			backend = env
		}
	}
	if backend == "" {
		backend = "ssm"
	}
	lb := strings.ToLower(backend)
	switch lb {
	case "null", "ssm", "secretsmanager", "s3", "s3-kms":
		return lb, nil
	default:
		return "", fmt.Errorf("Failed to get secret store: invalid backend `%s`", strings.ToUpper(backend))
	}
}

func resolveBackendExport(cmd *cobra.Command) (string, error) {
	backend := backendFlag
	if !cmd.Root().PersistentFlags().Changed("backend") && !cmd.Flags().Changed("backend") && !cmd.PersistentFlags().Changed("backend") {
		if env := os.Getenv("CHAMBER_SECRET_BACKEND"); env != "" {
			backend = env
		}
	}
	if backend == "" {
		backend = "ssm"
	}
	lb := strings.ToLower(backend)
	switch lb {
	case "null", "ssm", "secretsmanager", "s3", "s3-kms":
		bucket := getEffectiveS3Bucket(cmd)
		if (lb == "s3" || lb == "s3-kms") && bucket == "" {
			return "", fmt.Errorf("Must set bucket for s3 backend")
		}
		return lb, nil
	default:
		return "", fmt.Errorf("invalid backend `%s`", strings.ToUpper(backend))
	}
}

func bucketMissingError() error {
	return fmt.Errorf("Failed to get secret store: Must set bucket for s3 backend")
}

func listCmd() *cobra.Command {
	var expand bool
	var t, u, v bool
	cmd := &cobra.Command{
		Use:   "list <service>",
		Short: "List the secrets set for a service",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := checkRetriesEnv(cmd); err != nil {
				return fmt.Errorf("Failed to get secret store: %w", err)
			}
			backend, err := resolveBackend(cmd)
			if err != nil {
				return err
			}
			switch backend {
			case "null":
				if expand {
					fmt.Println("Key\tVersion\t\tLastModified\tUser\tValue")
				} else {
					fmt.Println("Key\tVersion\t\tLastModified\tUser")
				}
				return nil
			case "ssm":
				return fmt.Errorf("Failed to list store contents: operation error SSM: DescribeParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			case "secretsmanager":
				return fmt.Errorf("Failed to list store contents: operation error Secrets Manager: GetSecretValue, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			case "s3":
				bucket := getEffectiveS3Bucket(cmd)
				if bucket == "" {
					return bucketMissingError()
				}
				return fmt.Errorf("Failed to list store contents: operation error S3: GetObject, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
			case "s3-kms":
				bucket := getEffectiveS3Bucket(cmd)
				if bucket == "" {
					return bucketMissingError()
				}
				return fmt.Errorf("Failed to list store contents: operation error S3: ListObjectsV2, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
			}
			return nil
		},
	}
	cmd.Flags().SortFlags = false
	cmd.Flags().BoolVarP(&expand, "expand", "e", false, "Expand parameter list with values")
	cmd.Flags().BoolVarP(&t, "time", "t", false, "Sort by modified time")
	cmd.Flags().BoolVarP(&u, "user", "u", false, "Sort by user")
	cmd.Flags().BoolVarP(&v, "version", "v", false, "Sort by version")
	return cmd
}

func readCmd() *cobra.Command {
	var quiet bool
	var ver int
	cmd := &cobra.Command{
		Use:   "read <service> <key>",
		Short: "Read a specific secret from the parameter store",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := checkRetriesEnv(cmd); err != nil {
				return fmt.Errorf("Failed to get secret store: %w", err)
			}
			backend, err := resolveBackend(cmd)
			if err != nil {
				return err
			}
			switch backend {
			case "null":
				return fmt.Errorf("Failed to read: Not implemented for Null Store")
			case "ssm":
				return fmt.Errorf("Failed to read: operation error SSM: GetParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			case "secretsmanager":
				return fmt.Errorf("Failed to read: operation error Secrets Manager: GetSecretValue, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			case "s3":
				bucket := getEffectiveS3Bucket(cmd)
				if bucket == "" {
					return bucketMissingError()
				}
				return fmt.Errorf("Failed to read: operation error S3: GetObject, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
			case "s3-kms":
				bucket := getEffectiveS3Bucket(cmd)
				if bucket == "" {
					return bucketMissingError()
				}
				return fmt.Errorf("Failed to read: operation error S3: GetObject, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
			}
			return nil
		},
	}
	cmd.Flags().SortFlags = false
	cmd.Flags().BoolVarP(&quiet, "quiet", "q", false, "Only print the secret")
	cmd.Flags().IntVarP(&ver, "version", "v", -1, "The version number of the secret. Defaults to latest.")
	return cmd
}

func writeCmd() *cobra.Command {
	var singleLine bool
	var skipUnchanged bool
	var tags map[string]string
	cmd := &cobra.Command{
		Use:   "write <service> <key> [--] <value|->",
		Short: "write a secret",
		Args:  cobra.ExactArgs(3),
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := checkRetriesEnv(cmd); err != nil {
				return fmt.Errorf("Failed to get secret store: %w", err)
			}
			backend, err := resolveBackend(cmd)
			if err != nil {
				return err
			}
			hasTags := len(tags) > 0
			switch backend {
			case "null":
				if hasTags {
					return fmt.Errorf("WriteWithTags is not implemented for Null Store")
				}
				return fmt.Errorf("Write is not implemented for Null Store")
			case "ssm":
