				}
				if err := os.WriteFile(outputFile, []byte(content), 0644); err != nil {
					return fmt.Errorf("Failed to open output file for writing: %v", err)
				}
				return nil
			}
			switch backend {
			case "null":
				switch f {
				case "json", "yaml":
