			if outputFile != "" {
				_, err := os.Create(outputFile)
				if err != nil {
					return fmt.Errorf("Failed to open output file for writing: %v", err)
				}
				var content string
				switch f {
				case "json", "yaml":
					content = "{}\n"
				default:
					content = ""
				}
				if err := os.WriteFile(outputFile, []byte(content), 0644); err != nil {
					return fmt.Errorf("Failed to open output file for writing: %v", err)
				}
				return nil
			}
			switch backend {
			case "null":
