					return bucketMissingError()
				}
				return fmt.Errorf("Failed to write tags: Not implemented for S3 Store")
			}
			return nil
		},
	}
	cmd.Flags().BoolVar(&del, "delete-other-tags", false, "Delete tags not specified in the command")
	return cmd
}

